module protocol::emode;

use std::type_name::TypeName;

use sui::table::{Self, Table};
use sui::dynamic_field;

use math::float::Decimal;
use protocol::generic_store::{Self, GenericCoinTypeStorage};
use protocol::error;
use x_oracle::x_oracle::{Self, BaseToken};
use protocol::limiter::{Self, Limiter, NewLimiter};
use protocol::limiter::RateLimitUsage;

public struct EModeCollateral has store {
    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,
}

public struct EModeBorrow has store {
    max_borrow_amount: u64,
    borrow_weight: Decimal,
}

public struct EModeFlashLoan has store {
    flash_loan_fee_rate: Decimal,
}

public struct EModeRateLimiter has store {
    deposit: Limiter,
    borrow: Limiter,
}

public struct EMode has key, store {
    id: UID,

    // dynamic fields:
    // - collateral: EModeCollateral,
    // - borrow: EModeBorrow,
    // - flashloan: EModeFlashLoan,
    // - limiter: EModeRateLimiter,
}

public struct EModeGroup has store {
    assets: GenericCoinTypeStorage<EMode>,
    assets_borrows: GenericCoinTypeStorage<Decimal>,
    oracle_base_token: BaseToken,
}

public struct EModeGroupRegistry has store {
    next_group_id: u8,
    groups: Table<u8, EModeGroup>,
}

public(package) fun new_e_mode_registry(ctx: &mut TxContext): EModeGroupRegistry {
    EModeGroupRegistry {
        next_group_id: 0,
        groups: table::new(ctx)
    }
}

/// Create a new e mode group and returns the e mode id
public(package) fun new_emode_group(registry: &mut EModeGroupRegistry, oracle_base_token: u8, ctx: &mut TxContext): u8 {
    let next_id = registry.next_group_id;
    assert!(next_id != std::u8::max_value!(), error::max_emode_groups_reached());

    registry.next_group_id = registry.next_group_id + 1;

    registry.groups.add(
        next_id,
        EModeGroup {
            oracle_base_token: x_oracle::base_token_from_u8(oracle_base_token),
            assets_borrows: generic_store::new<Decimal>(ctx),
            assets: generic_store::new<EMode>(ctx)
        }
    );

    next_id
}

public(package) fun get_oracle_base_token(self: &EModeGroup): BaseToken { self.oracle_base_token }

/// Add a new asset configuration into the emode registry
public struct NewEMode has copy, drop, store {
    collateral_factor: Decimal,
    liquidation_factor: Decimal,
    liquidation_incentive: Decimal,

    max_borrow_amount: u64,
    borrow_weight: Decimal,

    flash_loan_fee_rate: Decimal,

    deposit_limiter: NewLimiter,
    borrow_limiter: NewLimiter,
}

public(package) fun new_emode_params(
    collateral_factor: Decimal,

